function Signals() {
  const [model, setModel] = useState("all");
  const [data, setData] = useState<any>(null);
  const [statusData, setStatusData] = useState<any>(null);
  const [refreshing, setRefreshing] = useState("");
  const [message, setMessage] = useState("");
  const load = useCallback(async () => {
    const query = new URLSearchParams({ model, abcd_mode: "latest" });
    const selected = await request(`/recommendations?${query.toString()}`);
    setData(selected);
    if (model === "all") setStatusData(selected);
    else {
      const statusQuery = new URLSearchParams({ model: "all", abcd_mode: "latest" });
      setStatusData(await request(`/recommendations?${statusQuery.toString()}`));
    }
  }, [model]);
  useEffect(() => {
    void load();
    const timer = setInterval(() => void load(), 30_000);
    return () => clearInterval(timer);
  }, [load]);
  const modelStatuses = statusData?.dataStatus?.models || data?.dataStatus?.models || [];
  const statusByModel = new Map(modelStatuses.map((item: any) => [item.modelKey, item]));
  const refresh = async (key: string) => {
    setRefreshing(key); setMessage("");
    try {
      const queued = await request("/recommendations/refresh", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ model: key }) });
      setMessage(`${key.toUpperCase()} 原版任务已在后台运行，网页可继续使用。`);
      let job: any = null;
      for (let attempt = 0; attempt < 450; attempt += 1) {
        await new Promise((resolve) => setTimeout(resolve, 2000));
        job = await request(`/jobs/${queued.jobId}`);
        if (job.status !== "running") break;
      }
      if (!job || job.status === "running") throw new Error("任务仍在后台运行，可稍后在数据中枢查看结果");
      if (job.status !== "success") throw new Error(job.error || job.message || "刷新失败，上一发布版已保留");
      setMessage(`${key.toUpperCase()} 已生成 ${job.result?.count ?? job.rows_changed ?? 0} 只；${job.result?.sourceMessage || job.message}`); await load();
    }
    catch (error) { setMessage(error instanceof Error ? error.message : "刷新失败"); }
    finally { setRefreshing(""); }
  };
  return <div className="page-stack signals-page">
    <section className="panel recommendations-primary">
      <SectionTitle eyebrow="TODAY'S PICKS" title="今日推荐" note="先看实际入选股票；数据血缘、权重与健康检查已收进下方详情。" action={<div className="segmented">{[["all","综合"],["abcd","ABCD"],["aia","AIA"],["heat","热度"]].map(([key,label]) => <button className={model === key ? "active" : ""} onClick={() => setModel(key)} key={key}>{label}</button>)}</div>} />
      {!data ? <Loading /> : (data.items || []).length ? <div className="recommend-core-list">{(data.items || []).map((item: any, index: number) => { const sources = item.sources?.length ? item.sources : [item.model_key]; return <article key={`${item.code}-${index}`}><header><b>{String(item.rank || index + 1).padStart(2,"0")}</b><span><strong>{item.name}</strong><small>{item.code} · {item.industry}</small></span><div className="badges">{sources.map((source:string)=><Badge key={source} tone={source === "abcd" ? "cyan" : source === "heat" ? "amber" : "violet"}>{source.toUpperCase()}</Badge>)}</div></header><div className="recommend-core-score"><strong>{formatNumber(item.score)}</strong><span>策略分</span><b>{formatNumber(item.close,2)}<small className={Number(item.pct_chg)>=0?"rise":"fall"}>{Number(item.pct_chg)>=0?"+":""}{formatNumber(item.pct_chg,2)}%</small></b></div><p>{item.reason}</p><footer><span>发布 {formatDataTime(item.generated_at)}</span><span>{item.risk || "仅供研究参考"}</span></footer></article>; })}</div> : <div className="core-empty"><strong>当前没有可发布推荐</strong><span>模型未通过硬门槛时保持为空，不会用全市场评分前五冒充策略推荐。</span></div>}
    </section>
    {message && <div className="notice">{message}</div>}
    <section className="notice signal-lock-note"><strong>ABCD盘中推荐：默认从09:45生成首批</strong><span>推荐页始终展示最新成功发布批次；点击手动刷新会重新获取当前AKShare盘中行情并按原8010逻辑重算。09:45信号仅在模拟账户中单独留档，不限制本页更新。</span></section>
    <section className="model-refresh-grid">
      {[{ key: "abcd", name: "盘中 ABCD", note: "09:45生成首批；此后可按当前行情手动重算", tag: "LIVE", tone: "cyan" }, { key: "aia", name: "AIA Top10", note: "只读同步权威Top10；本机不生成或重排", tag: "READ ONLY", tone: "violet" }, { key: "heat", name: "热度优先", note: "8002原版兼容；当天热榜与两阶段排名", tag: "8002", tone: "amber" }].map((item) => { const status: any = statusByModel.get(item.key); const complete = status?.status === "ready"; return <article key={item.key}><div><Badge tone={item.tone}>{item.tag}</Badge><span>{item.note}</span></div><h3>{item.name}</h3><p>{item.key === "abcd" ? "完全复用原8010的ABCD评分、硬门槛、行业限额和排序；手动刷新产生并保留新的盘中推荐，不改写模拟账户单独保存的09:45交易信号。" : item.key === "aia" ? "从已校验的权威AIA v6批次原序导入10只股票及分数；本机不扫描候选、不改权重、不重算或重排。" : "对应8002热度优先选股：五平台热度、四Agent、前日板块动量、原8002去市值分、淘股吧情绪和日线启动组成第一阶段，随后按四Agent等权复评分。"}</p><div className="model-card-audit"><span><small>发布时间</small><strong>{formatDataTime(status?.publishedAt)}</strong></span><span><small>数据状态</small><strong className={complete ? "complete" : "partial"}>{complete ? `完备 ${formatNumber(status?.fieldCoverage, 1)}%` : status?.completeness === "complete" ? `字段完整·快照需检查` : status ? `不完备 ${formatNumber(status.fieldCoverage, 1)}%` : "待核验"}</strong></span><span><small>数据截止</small><strong>{formatDataTime(status?.quoteAsOf || status?.factorAsOf)}</strong></span></div><button disabled={refreshing === item.key} onClick={() => refresh(item.key)}>{refreshing === item.key ? "模型运行中…" : item.key === "abcd" ? "按最新盘中数据刷新" : item.key === "aia" ? "同步权威AIA Top10" : "运行8002热度选股"}</button></article>; })}
    </section>
    <details className="secondary-disclosure">
      <summary><span><strong>策略权重与数据审计</strong><small>需要时展开查看版本、完备性和全部权重</small></span><b>展开</b></summary>
      <div className="secondary-disclosure-body"><RecommendationDataStatus value={(statusData || data)?.dataStatus} /><WeightStudio /></div>
    </details>
  </div>;
}

type FilterRow = { key: string; operator: string; value: number };
type WeightRow = { key: string; weight: number; direction: "asc" | "desc" };
function Screener() {
  const [definitions, setDefinitions] = useState<any[]>([]);
  const [filters, setFilters] = useState<FilterRow[]>([]);
  const [weightRows, setWeightRows] = useState<WeightRow[]>([]);
  const [result, setResult] = useState<any>(null);
  const [executedSignature, setExecutedSignature] = useState("");
  const [loading, setLoading] = useState(false);
  const [daily, setDaily] = useState<any>(null);
  const [dailyForm, setDailyForm] = useState({ strategyId: "daily-custom", name: "自定义每日候选", ruleTag: "自定义", runTime: "08:10", enabled: false, limit: 20 });
  const [dailyBusy, setDailyBusy] = useState("");
  const [dailyMessage, setDailyMessage] = useState("");
  const applyDailyStrategy = useCallback((strategy:any)=>{if(!strategy)return;setDailyForm({strategyId:strategy.strategyId,name:strategy.name,ruleTag:strategy.ruleTag||"自定义",runTime:strategy.runTime,enabled:Boolean(strategy.enabled),limit:Number(strategy.limit||20)});setFilters(strategy.filters||[]);setWeightRows(Object.entries(strategy.weights||{}).map(([key,weight])=>({key,weight:Number(weight),direction:strategy.weightDirections?.[key]==="asc"?"asc":"desc"} as WeightRow)));setResult(null);setExecutedSignature("");},[]);
  const loadDaily = useCallback(async(strategyId?:string)=>{const value=await request(`/screener/daily${strategyId?`?strategy_id=${encodeURIComponent(strategyId)}`:""}`);setDaily(value);if(value.strategy)applyDailyStrategy(value.strategy);},[applyDailyStrategy]);
  useEffect(() => { request("/factors").then(factorData=>setDefinitions([...new Map((factorData.items || []).map((item: any) => [item.key, item])).values()]));void loadDaily(); }, [loadDaily]);
  const groups = useMemo(() => Object.entries(definitions.reduce((acc: any, item: any) => { (acc[item.group] ||= []).push(item); return acc; }, {})), [definitions]);
  const configSignature = useMemo(()=>JSON.stringify({filters,weightRows}),[filters,weightRows]);
  const visibleResult = executedSignature===configSignature ? result : null;
  const currentConfig = () => { const weights=Object.fromEntries(weightRows.map(row=>[row.key,row.weight]));const weightDirections=Object.fromEntries(weightRows.map(row=>[row.key,row.direction]));return {filters,weights,weightDirections,sort:{key:weightRows.length?"composite_score":filters[0]?.key||"ret_20d",direction:weightRows.length||definitions.find(item=>item.key===filters[0]?.key)?.direction!=="asc"?"desc":"asc"},limit:dailyForm.limit}; };
  const run = async () => { if(!filters.length&&!weightRows.length){setDailyMessage("请先加入至少一项硬筛或加权因子。");return;}const signature=configSignature;setLoading(true); try { const payload=await request("/screener", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({...currentConfig(),limit:100}) });setResult(payload);setExecutedSignature(signature); } finally { setLoading(false); } };
  const saveDaily = async()=>{if(!filters.length&&!weightRows.length)throw new Error("请先配置当前筛选规则");const payload=await request("/screener/daily/config",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...dailyForm,config:currentConfig()})});setDaily(payload);if(payload.strategy)applyDailyStrategy(payload.strategy);return payload;};
  const saveSchedule = async()=>{setDailyBusy("save");setDailyMessage("");try{await saveDaily();setDailyMessage(dailyForm.enabled?`已保存并启用，交易日 ${dailyForm.runTime} 自动生成。`:"规则已保存，自动执行目前关闭。");}catch(error){setDailyMessage(error instanceof Error?error.message:"保存失败");}finally{setDailyBusy("");}};
  const generateDaily = async()=>{setDailyBusy("run");setDailyMessage("");try{await saveDaily();const payload=await request("/screener/daily/run",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({strategyId:dailyForm.strategyId})});await loadDaily(dailyForm.strategyId);setDailyMessage(payload.status==="published"?`已按“${dailyForm.name}”固化 ${payload.rows?.length||0} 只候选。`:payload.message);}catch(error){setDailyMessage(error instanceof Error?error.message:"生成失败");}finally{setDailyBusy("");}};
  const selectDailyStrategy = (strategy:any)=>{applyDailyStrategy(strategy);setDailyMessage(`已切换到规则“${strategy.name}”。`);};
  const deleteDailyStrategy = async(strategy:any)=>{if(strategy.strategyId==="daily-custom"){setDailyMessage("默认规则不能删除，只能停用。");return;}if(!window.confirm(`确认删除规则“${strategy.name}”？历史候选批次会保留，但该规则不再出现在自动执行列表。`))return;setDailyBusy("delete");try{const payload=await request(`/screener/daily/${encodeURIComponent(strategy.strategyId)}`,{method:"DELETE"});setDaily(payload);if(payload.strategy)applyDailyStrategy(payload.strategy);setDailyMessage(`规则“${strategy.name}”已删除。`);}catch(error){setDailyMessage(error instanceof Error?error.message:"删除失败");}finally{setDailyBusy("");}};
  const createDailyStrategy = ()=>{const strategy={strategyId:`daily-${Date.now()}`,name:"新量价规则",ruleTag:"未标记",runTime:"08:10",enabled:false,limit:20,filters:[],weights:{},weightDirections:{}};setDaily(current=>({...current, strategy, strategies:[...(current?.strategies||[]),strategy]}));applyDailyStrategy(strategy);setDailyMessage("已创建未保存规则，请配置条件后保存。");};
  const addFilter = (key: string) => { if (!filters.some((item) => item.key === key)) setFilters([...filters, { key, operator: ">=", value: 0 }]); };
  const addWeight = (key: string) => { if (!weightRows.some((item) => item.key === key)) { const definition=definitions.find(item=>item.key===key); setWeightRows([...weightRows,{key,weight:10,direction:definition?.direction||"desc"}]); } };
  const changeFilterKey = (index:number,key:string) => { if(filters.some((item,i)=>i!==index&&item.key===key))return;setFilters(filters.map((row,i)=>i===index?{...row,key}:row)); };
  const changeWeightKey = (index:number,key:string) => { if(weightRows.some((item,i)=>i!==index&&item.key===key))return;const definition=definitions.find(item=>item.key===key);setWeightRows(weightRows.map((row,i)=>i===index?{...row,key,direction:definition?.direction||"desc"}:row)); };
  const latestDaily=daily?.latestPublished;
  return <div className="screener-layout"><div className="strategy-edit-hint"><strong>已有自动化规则</strong><span>点击“编辑”载入条件；修改后点击“保存当前规则”覆盖当前规则。</span></div>
      <aside className="panel factor-library"><SectionTitle eyebrow="FACTOR LIBRARY" title={`${definitions.length}项中文因子`} note="先从完整因子库自由加入硬筛或加权；板块四日连涨为是/否条件，只能作为硬筛。" />{groups.map(([group, items]: any) => <div className="factor-group" key={group}><strong>{group}</strong><div>{items.map((item: any) => <article key={item.key} className={item.availability === "training_required" ? "factor-pending" : ""} title={`${item.name} · ${item.unit} · 用于${item.usedBy.join("、") || "通用筛选"}`}><span>{item.name}<small>{item.availability === "training_required" ? "待正样本与夜间训练" : item.filterOnly ? "仅硬筛" : item.usedBy.join(" / ") || "通用"}</small></span><div className="factor-actions"><button onClick={() => addFilter(item.key)}>硬筛</button>{!item.filterOnly&&<button onClick={() => addWeight(item.key)}>加权</button>}</div></article>)}</div></div>)}</aside>
    <section className="page-stack">
      <article className="panel filter-builder"><SectionTitle eyebrow="HARD FILTER" title="自由硬筛条件" note="全部因子均可选择；5/10/30日前50交集、板块5日排名与BigQuant热度排名均已进入正式因子库。" action={<div className="builder-actions"><button onClick={()=>definitions[0]&&addFilter(definitions.find(item=>!filters.some(row=>row.key===item.key))?.key||definitions[0].key)}>＋ 条件</button><button className="primary" onClick={run}>{loading ? "计算中…" : "运行筛选"}</button></div>} /><div className="filter-rows">{filters.length===0&&<div className="builder-empty">尚未加入硬筛条件；可以只设加权，也可以从左侧自由添加。</div>}{filters.map((filter, index) => <div className="filter-row" key={`${filter.key}-${index}`}><select value={filter.key} onChange={event=>changeFilterKey(index,event.target.value)}>{definitions.map(item=><option key={item.key} value={item.key}>{item.name}（{item.unit}）</option>)}</select><select value={filter.operator} onChange={(event) => setFilters(filters.map((row,i) => i===index?{...row,operator:event.target.value}:row))}><option>&gt;=</option><option>&gt;</option><option>&lt;=</option><option>&lt;</option><option>=</option></select><input type="number" step="0.01" value={filter.value} onChange={(event) => setFilters(filters.map((row,i) => i===index?{...row,value:Number(event.target.value)}:row))}/><button onClick={() => setFilters(filters.filter((_,i)=>i!==index))}>×</button></div>)}</div></article>
      <article className="panel weight-builder"><SectionTitle eyebrow="WEIGHTED RANKING" title="自由加权评分" note="任意因子先做全市场百分位，再按相对权重合成0–100分；可单独选择偏高或偏低更优。" action={<button className="add-line" onClick={()=>{const next=definitions.find(item=>!weightRows.some(row=>row.key===item.key));if(next)addWeight(next.key);}}>＋ 加权因子</button>} /><div className="weight-rows">{weightRows.length===0&&<div className="builder-empty">尚未加入加权因子。</div>}{weightRows.map((row,index)=><div className="weight-row" key={`${row.key}-${index}`}><select value={row.key} onChange={event=>changeWeightKey(index,event.target.value)}>{definitions.map(item=><option key={item.key} value={item.key}>{item.name}（{item.unit}）</option>)}</select><select value={row.direction} onChange={event=>setWeightRows(weightRows.map((item,i)=>i===index?{...item,direction:event.target.value as "asc"|"desc"}:item))}><option value="desc">数值越高越优</option><option value="asc">数值越低越优</option></select><input type="range" min="0" max="100" step="1" value={row.weight} onChange={event=>setWeightRows(weightRows.map((item,i)=>i===index?{...item,weight:Number(event.target.value)}:item))}/><input type="number" min="0" max="1000" step="1" value={row.weight} onChange={event=>setWeightRows(weightRows.map((item,i)=>i===index?{...item,weight:Number(event.target.value)}:item))}/><button onClick={()=>setWeightRows(weightRows.filter((_,i)=>i!==index))}>×</button></div>)}</div></article>
      <article className="panel screener-schedule"><SectionTitle eyebrow="DAILY CANDIDATES" title="量价筛选自动化规则" note="规则可新增、命名、标记并独立启用；每次执行读取最新筹码模型排名截面，不沿用旧模型分。" /><div className="strategy-list"><div className="strategy-list-head"><strong>已保存规则</strong><button onClick={createDailyStrategy}>＋ 新建规则</button></div>{(daily?.strategies||[]).map((strategy:any)=><div className={`strategy-list-entry ${strategy.strategyId===dailyForm.strategyId?"active":""}`} key={strategy.strategyId}><button type="button" className="strategy-list-item" onClick={()=>selectDailyStrategy(strategy)}><span><strong>{strategy.name}</strong><small>{strategy.ruleTag||"自定义"} · {strategy.runTime} · v{strategy.revision}</small></span><Badge tone={strategy.enabled?"green":"amber"}>{strategy.enabled?"已启用":"已停用"}</Badge></button><button type="button" className="strategy-edit-button" onClick={()=>selectDailyStrategy(strategy)}>编辑</button>{strategy.strategyId==="daily-custom"?<span className="strategy-default-label">默认</span>:<button type="button" className="strategy-delete" onClick={event=>{event.stopPropagation();void deleteDailyStrategy(strategy);}}>删除</button>}</div>)}</div><div className="screener-strategy-top"><div><label>规则名称<input value={dailyForm.name} onChange={event=>setDailyForm({...dailyForm,name:event.target.value})}/></label><label>规则标记<input value={dailyForm.ruleTag} onChange={event=>setDailyForm({...dailyForm,ruleTag:event.target.value})} placeholder="例如：突破 / 低回撤"/></label><label>交易日执行时间<input type="time" value={dailyForm.runTime} onChange={event=>setDailyForm({...dailyForm,runTime:event.target.value})}/></label><label>输出数量<input type="number" min="1" max="100" value={dailyForm.limit} onChange={event=>setDailyForm({...dailyForm,limit:Number(event.target.value)})}/></label><label className="schedule-switch"><input type="checkbox" checked={dailyForm.enabled} onChange={event=>setDailyForm({...dailyForm,enabled:event.target.checked})}/><span>启用自动生成</span></label></div><aside><button onClick={saveSchedule} disabled={Boolean(dailyBusy)}>{dailyBusy==="save"?"保存中…":"保存当前规则"}</button><button className="primary" onClick={generateDaily} disabled={Boolean(dailyBusy)}>{dailyBusy==="run"?"生成中…":"按当前规则立即生成"}</button></aside></div>{dailyMessage&&<div className="notice">{dailyMessage}</div>}{daily?.latestAttempt?.status==="rejected"&&<div className="candidate-rejected"><strong>最近一次未发布</strong><span>{daily.latestAttempt.message}</span></div>}{latestDaily?<div className="daily-candidate-result"><header><span><strong>{latestDaily.itemCount}只候选</strong><small>规则v{latestDaily.strategyRevision} · 因子 {latestDaily.factorDate} · 模型排名 {latestDaily.dataStatus?.modelSnapshot?.rankDate||"—"} · 多周期模型 {latestDaily.dataStatus?.modelSnapshot?.multiPeriodModelVersion||"未训练"}</small></span><b>{formatDataTime(latestDaily.generatedAt)}</b></header><div>{(latestDaily.rows||[]).map((row:any)=><article key={row.code}><b>{row.rank}</b><span><strong>{row.name}</strong><small>{row.code} · {row.industry}</small></span><em>{formatNumber(row.composite_score)}</em><span>板块#{row.sector_ret_5d_rank||"—"}<small>5/10/30交集 {row.stock_top50_5_10_30?"是":"否"}</small></span><span>热度#{row.bigquant_heat_rank||"—"}<small>{row.bigquant_heat_date||"—"}</small></span></article>)}</div></div>:<div className="builder-empty">当前规则尚无已发布批次。保存规则不会自动输出股票，只有到达执行时间或点击立即生成后才会形成结果。</div>}</article>
      <article className="panel screener-results"><SectionTitle eyebrow="RANKED UNIVERSE" title={visibleResult?`筛选结果 ${visibleResult.total ?? 0}只`:"等待执行筛选"} note={visibleResult?`因子截面 ${visibleResult.factorDate||"—"} · ${filters.length}项硬筛 · ${weightRows.length}项自定义加权 · 结果只反映本次配置`:`配置上方硬筛与加权条件后点击“运行筛选”；执行前不输出任何股票。`} />{loading?<Loading />:!visibleResult?<div className="screener-idle"><strong>尚未执行</strong><span>当前不会展示默认榜单或沿用上一次的旧结果。</span></div>:<>{visibleResult.message&&<div className="notice">{visibleResult.message}</div>}<div className="screen-table"><div className="screen-head"><span>排名 / 股票</span><span>自定义加权分</span><span>20日动量</span><span>60日涨幅</span><span>60日排名</span><span>板块四日连涨</span><span>量比</span><span>正式模型</span><span>候选模型</span><span>待建模型</span><span>AIA形态</span><span>五平台热度</span></div>{visibleResult.rows.map((row:any,index:number)=><div className="screen-row" key={row.code}><span className="stock"><b>{index+1}</b><strong>{row.name}<small>{row.code} · {row.industry}</small></strong></span><strong className="purple-score">{formatNumber(row.composite_score)}<small>{weightRows.length?`${weightRows.length}项因子合成`:"未设置加权"}</small></strong><span className={Number(row.ret_20d)>=0?"rise":"fall"}>{(Number(row.ret_20d)*100).toFixed(1)}%</span><span className={Number(row.ret_60d)>=0?"rise":"fall"}>{row.ret_60d==null?"—":`${(Number(row.ret_60d)*100).toFixed(1)}%`}</span><span>{row.stock_ret_60d_rank||"—"}</span><span>{Number(row.sector_4d_streak)===1?"是":"否"}</span><span>{formatNumber(row.volume_ratio_20,2)}</span><span>{formatNumber(row.formal_model_score,3)}<small>#{row.formal_model_rank}</small></span><span>{formatNumber(row.candidate_model_score,3)}<small>#{row.candidate_model_rank}</small></span><span>{formatNumber(row.multi_period_model_score,3)}<small>#{row.multi_period_model_rank || "—"}</small></span><span>{formatNumber(row.aia_technical_pattern)}</span><span>{formatNumber(row.five_platform_heat)}</span></div>)}</div></>}</article>
    </section>
  </div>;
}

function Chip() {
  const modelLabels:Record<string,string>={candidate:"候选筹码模型",formal:"正式筹码模型",multi_period:"多周期候选模型"};
  const [samples, setSamples] = useState<any>(null);
  const [distributions, setDistributions] = useState<any>(null);
  const [selectedProfile, setSelectedProfile] = useState<any>(null);
  const [activeScope, setActiveScope] = useState("candidate");
  const [samplePolarity, setSamplePolarity] = useState("all");
  const [form, setForm] = useState({ scope: "candidate", sampleLabel: 1, code: "300142.SZ", tradeDate: "2026-08-19", reason: "人工确认的筹码正样本" });
  const [message, setMessage] = useState("");
  const load = useCallback(async () => { const s=await request("/chip/samples");setSamples(s);request("/chip/sample-distributions").then(setDistributions).catch(()=>undefined); },[]);
  useEffect(()=>{void load();},[load]);
  const add = async()=>{const modelName=modelLabels[activeScope]||activeScope;const kind=form.sampleLabel===1?"正样本":"负样本";try{await request("/chip/samples",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,scope:activeScope})});setMessage(activeScope==="multi_period"?`${modelName}：${kind}已写入隔离样本库；当前只收集，不触发生产训练。`:`${modelName}：${kind}已登记，该模型已进入夜间重训队列。`);await load();}catch(error){setMessage(error instanceof Error?`${modelName}：${error.message}`:`${modelName}：新增失败`);}};
  const remove = async(sample:any)=>{const modelName=modelLabels[sample.scope]||sample.scope;const kind=Number(sample.sample_label)===1?"正样本":"负样本";if(!window.confirm(`确认从“${modelName}”删除${kind} ${sample.name} ${sample.trade_date}？\n此操作只影响该模型的样本库。`))return;try{await request(`/chip/samples/${sample.sample_id}`,{method:"DELETE"});setMessage(`${modelName}：${kind}已删除${sample.scope==="multi_period"?"。":"，该模型已进入夜间重训队列。"}`);await load();}catch(error){setMessage(error instanceof Error?`${modelName}：${error.message}`:`${modelName}：删除失败`);}};
  const profileMap = useMemo<Map<string, any>>(()=>new Map((distributions?.profiles||[]).map((profile:any)=>[`${profile.code}|${profile.tradeDate}`,profile])),[distributions]);
  const scopedSamples=(samples?.samples||[]).filter((sample:any)=>sample.scope===activeScope);
  const visibleSamples=scopedSamples.filter((sample:any)=>samplePolarity==="all"||Number(sample.sample_label)===(samplePolarity==="positive"?1:0));
  const polarityCount=(polarity:string)=>polarity==="all"?scopedSamples.length:scopedSamples.filter((sample:any)=>Number(sample.sample_label)===(polarity==="positive"?1:0)).length;
  const activeModel=(samples?.registry||[]).find((model:any)=>model.scope===activeScope);
  const selectModel=(scope:string)=>{setActiveScope(scope);setForm(current=>({...current,scope}));setSamplePolarity("all");setMessage("");setSelectedProfile(null);};
  return <div className="page-stack">
    <section className="dual-model-hero"><div><span>LABELED SAMPLE LAB</span><h2>筹码正负样本与训练管理</h2><p>先点击右侧模型卡片，再查看、增加或删除该模型的正负样本。正式与候选模型的样本修订进入夜间重训；多周期候选模型保持隔离，当前没有正样本且不会参与生产训练。</p></div><div className="dual-model-cards" role="tablist" aria-label="选择筹码模型">{(samples?.registry||[]).map((model:any)=>{const experimental=!model.production_enabled;return <button type="button" role="tab" aria-selected={activeScope===model.scope} className={`model-sample-card ${activeScope===model.scope?"active":""}`} onClick={()=>selectModel(model.scope)} key={model.scope}><span>{model.display_name}</span><strong>{experimental?"待建样本":model.model_version?.match(/v\d+/)?.[0] || model.model_version}</strong><small>正 {model.positive_count||0} · 负 {model.negative_count||0} · 修订 {model.revision}/{model.applied_revision}</small><Badge tone={experimental?"amber":model.pending_retrain?"amber":"green"}>{experimental?"未训练·未上线":model.pending_retrain?"待夜间重训":"训练版本已应用"}</Badge></button>})}</div></section>
    <section className="sample-grid"><article className="panel sample-form"><SectionTitle eyebrow="LABELED SAMPLE" title={`新增${form.sampleLabel===1?"正":"负"}样本`} note={activeScope==="multi_period"?"第三模型当前没有正样本；新增内容仅进入隔离样本库，不触发生产训练。":"正负样本的增删都会增加当前模型修订号，并进入夜间重训队列。"} /><div className={`sample-target ${activeScope}`}><span>当前操作模型</span><strong>{modelLabels[activeScope]}</strong><small>{activeScope==="multi_period"?`当前正样本 ${activeModel?.positive_count||0} · 隔离收集`:"只修改该模型，不影响其他筹码模型"}</small></div><fieldset className="sample-label-field"><legend>样本类型</legend><div className="sample-label-switch" role="group" aria-label="选择正样本或负样本"><button type="button" className={form.sampleLabel===1?"active positive":""} onClick={()=>setForm({...form,sampleLabel:1,reason:"人工确认的筹码正样本"})}>正样本</button><button type="button" className={form.sampleLabel===0?"active negative":""} onClick={()=>setForm({...form,sampleLabel:0,reason:"人工确认的筹码负样本"})}>负样本</button></div></fieldset><label>证券代码<input value={form.code} onChange={e=>setForm({...form,code:e.target.value.toUpperCase()})}/></label><label>交易日<input value={form.tradeDate} onChange={e=>setForm({...form,tradeDate:e.target.value})}/></label><label>标注理由<textarea value={form.reason} onChange={e=>setForm({...form,reason:e.target.value})}/></label><button className="primary" onClick={add}>登记{form.sampleLabel===1?"正":"负"}样本到{modelLabels[activeScope]}</button>{message&&<p className="form-message">{message}</p>}</article><article className="panel sample-list"><SectionTitle eyebrow="SAMPLE REGISTRY" title={`${modelLabels[activeScope]} · ${visibleSamples.length}条`} note="当前列表和所有增删操作只属于已选中的模型。" action={<div className="sample-scope-filter" role="group" aria-label="按正负标签筛选样本">{[["all","全部"],["positive","正样本"],["negative","负样本"]].map(([polarity,label])=><button type="button" className={samplePolarity===polarity?"active":""} aria-pressed={samplePolarity===polarity} onClick={()=>setSamplePolarity(polarity)} key={polarity}>{label}<b>{polarityCount(polarity)}</b></button>)}</div>} />{distributions?.warning&&<div className="sample-warning">{distributions.warning}</div>}{visibleSamples.length?visibleSamples.map((sample:any)=>{const profile=profileMap.get(`${sample.code}|${sample.trade_date}`);const positive=Number(sample.sample_label)===1;return <div key={sample.sample_id}><span className="stock"><strong>{sample.name}<small>{sample.code} · {sample.trade_date}</small><em className={`sample-model-tag ${positive?"positive":"negative"}`}>{positive?"正样本":"负样本"}</em></strong></span><button className="chip-profile-button" aria-label={`查看${sample.name}在${modelLabels[sample.scope]||sample.scope}中的筹码分布`} onClick={()=>profile&&setSelectedProfile({...profile,name:sample.name,scope:sample.scope,sampleLabel:sample.sample_label})}><ChipProfileSvg profile={profile}/></button><span>{sample.reason}</span><Badge tone={sample.profile_ready?"green":"amber"}>{sample.profile_ready?"数据就绪":"待补数据"}</Badge><button title={`从${modelLabels[sample.scope]||sample.scope}删除${positive?"正":"负"}样本`} onClick={()=>remove(sample)}>删除</button></div>}):<div className="sample-empty">{samplePolarity==="all"?"该模型暂无样本":`该模型暂无${samplePolarity==="positive"?"正":"负"}样本`}</div>}</article></section>
    {selectedProfile&&<dialog open className="chip-modal" aria-label={`${selectedProfile.name}筹码分布`} onCancel={()=>setSelectedProfile(null)}><article><header><div><strong>{selectedProfile.name}</strong><small>{modelLabels[selectedProfile.scope]||selectedProfile.scope} · {Number(selectedProfile.sampleLabel)===1?"正样本":"负样本"} · {selectedProfile.code} · {selectedProfile.tradeDate} · 收盘 {formatNumber(selectedProfile.close,2)}</small></div><button onClick={()=>setSelectedProfile(null)}>×</button></header><ChipProfileSvg profile={selectedProfile} large/><footer><span><i className="profit"/> 获利筹码</span><span><i className="loss"/> 未获利筹码</span><span><i className="close-line"/> 收盘价</span></footer></article></dialog>}
  </div>;
}

/* Legacy K-line workbenches are retained only for migration comparison and are not mounted. */
/* eslint-disable @typescript-eslint/no-unused-vars, react-hooks/purity, jsx-a11y/no-noninteractive-tabindex */
function KlineShapeChart({bars,label,module}:{bars:any[];label:string;module:"m30"|"daily"}) {
  const rows=(bars||[]).filter((bar:any)=>[bar.open,bar.high,bar.low,bar.close].every((value:any)=>Number.isFinite(Number(value))));
  if(!rows.length)return <div className="kline-shape-empty">该股票暂无足够{label}数据</div>;
  const width=760,height=282,left=42,right=58,topPad=14,priceBottom=207,volumeTop=221,volumeBottom=260;const moving=module==="daily"?[{key:"ma5",label:"MA5",color:"#f0bd55"},{key:"ma30",label:"MA30",color:"#58a8ef"},{key:"ma250",label:"MA250 年线",color:"#d07ae8"}]:[{key:"ma5",label:"MA5",color:"#f0bd55"},{key:"ma20",label:"MA20 规则线",color:"#63c7a4"},{key:"ma30",label:"MA30",color:"#58a8ef"}];const priceValues=rows.flatMap((bar:any)=>[Number(bar.low),Number(bar.high),...moving.map(line=>Number(bar[line.key])).filter(Number.isFinite)]);const low=Math.min(...priceValues),high=Math.max(...priceValues),span=Math.max(.0001,high-low);const step=(width-left-right)/Math.max(1,rows.length);const x=(index:number)=>left+step*(index+.5);const y=(value:number)=>topPad+(high-value)/span*(priceBottom-topPad);const bodyWidth=Math.max(1.2,Math.min(5,step*.58));const maxVolume=Math.max(1,...rows.map((bar:any)=>Number(bar.volume)||0));const volumeY=(value:number)=>volumeBottom-(Math.max(0,value)/maxVolume)*(volumeBottom-volumeTop);const ticks=[0,Math.floor((rows.length-1)/3),Math.floor((rows.length-1)*2/3),rows.length-1].filter((value,index,array)=>array.indexOf(value)===index);const polyline=(key:string)=>rows.map((bar:any,index:number)=>Number.isFinite(Number(bar[key]))?`${x(index).toFixed(1)},${y(Number(bar[key])).toFixed(1)}`:"").filter(Boolean).join(" ");
  return <div className="kline-chart-frame"><svg className="kline-shape-chart" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${label}K线图，包含${moving.map(item=>item.label).join("、")}`} preserveAspectRatio="none"><g className="kline-grid">{[0,.25,.5,.75,1].map(value=><line key={value} x1={left} x2={width-right} y1={topPad+(priceBottom-topPad)*value} y2={topPad+(priceBottom-topPad)*value}/>)}</g>{rows.map((bar:any,index:number)=>{const xi=x(index),open=y(Number(bar.open)),close=y(Number(bar.close)),bodyTop=Math.min(open,close),body=Math.max(1.3,Math.abs(close-open)),up=Number(bar.close)>=Number(bar.open);return <g className={up?"up":"down"} key={`${bar.time}-${index}`}><title>{`${bar.time} 开${bar.open} 高${bar.high} 低${bar.low} 收${bar.close}`}</title><line x1={xi} x2={xi} y1={y(Number(bar.high))} y2={y(Number(bar.low))}/><rect x={xi-bodyWidth/2} y={bodyTop} width={bodyWidth} height={body}/><rect className="volume" x={xi-bodyWidth/2} y={volumeY(Number(bar.volume)||0)} width={bodyWidth} height={Math.max(1,volumeBottom-volumeY(Number(bar.volume)||0))}/></g>;})}{moving.map(line=>{const points=polyline(line.key);return points?<polyline className={`moving-line ${line.key}`} points={points} fill="none" stroke={line.color} strokeWidth={line.key==="ma250"?2.2:1.55} key={line.key}/>:null;})}<g className="kline-axis"><text x={width-right+7} y={topPad+4}>{high.toFixed(2)}</text><text x={width-right+7} y={(topPad+priceBottom)/2}>{((high+low)/2).toFixed(2)}</text><text x={width-right+7} y={priceBottom}>{low.toFixed(2)}</text>{ticks.map(index=><text textAnchor={index===0?"start":index===rows.length-1?"end":"middle"} x={x(index)} y={height-5} key={index}>{String(rows[index]?.time||"").replace("T"," ").slice(module==="daily"?2:5,module==="daily"?10:16)}</text>)}</g></svg><div className="kline-chart-legend"><span><i className="candle-up"/>上涨</span><span><i className="candle-down"/>下跌</span>{moving.map(line=><span key={line.key}><i style={{background:line.color}}/>{line.label}</span>)}<b>{rows.length}根 · 完整历史计算后截取展示</b></div></div>;
}

const klineReasonLabels:Record<string,string>={insufficient_history:"历史K线不足",platform_not_compact:"平台区间不够紧凑",platform_trending:"平台斜率过大",platform_closes_not_concentrated:"收盘价不够集中",breakout_not_confirmed:"尚未确认突破",breakout_candle_weak:"突破K线力度不足",ma20_not_just_turning_up:"MA20尚未刚转强",volume_not_confirmed:"量能未确认",breakout_overextended:"突破幅度已过度延伸",too_far_above_ma20:"距离MA20过远",recent_return_too_high:"短期涨幅过高",breakout_not_fresh:"突破已不新鲜",volume_blowoff:"成交量异常放大",long_upper_shadow:"上影线过长",failed_breakout:"突破后未能站稳",accelerated_extension:"日线加速延伸风险",confirmed_breakout:"未找到有效突破",close_far_below_ma250:"收盘偏离年线",volume_breakdown:"放量但价格没有推进",empty_bars:"行情为空"};
const m30ScoreLabels:Record<string,string>={platform:"平台紧凑度",ma20_turn:"MA20转强",breakout:"突破质量",anti_chase:"防追高",volume:"量能确认"};
const m30GateLabels:Record<string,string>={platform_width_ok:"平台振幅",platform_slope_ok:"平台斜率",platform_concentration_ok:"收盘集中度",breakout_confirmed:"突破确认",breakout_candle_ok:"突破K线",ma20_just_turned_up:"MA20刚转强",volume_confirmed:"量能确认",extension_ok:"突破延伸",ma20_distance_ok:"MA20距离",recent_return_ok:"近三根涨幅",fresh_breakout_ok:"突破新鲜度",volume_not_blowoff:"非末端爆量",upper_shadow_ok:"上影线",breakout_holding:"突破站稳"};
const dailyTemplateLabels:Record<string,string>={rising_narrow_base:"上升趋势窄平台",breakout_pullback_restart:"突破后缩量回踩再启动",ma250_convergence:"年线附近收敛平台"};
const dailyMetricLabels:Record<string,string>={pivot_price:"平台枢轴价",platform_width:"平台宽度",pivot_distance:"距枢轴",ma20:"MA20",ma60:"MA60",ma60_slope:"MA60斜率",volume_ratio:"量比",max_drawdown:"最大回撤",breakout_volume_ratio:"突破量比",pullback_volume_ratio:"回踩量比",restart_strength:"再启动强度",ma250:"MA250年线",ma250_slope:"年线斜率",near_ma250_ratio:"近年线占比",range_compression:"振幅收敛度"};
function klineMetric(value:unknown,key="") { const number=Number(value);if(!Number.isFinite(number))return String(value??"—");if(/ratio|width|distance|slope|drawdown|strength|compression/.test(key))return `${(number*100).toFixed(1)}%`;return number.toFixed(Math.abs(number)>=100?0:3); }

function KlineScoreEvidence({module,result}:{module:"m30"|"daily";result:any}) {
  if(module==="m30"){const template=result.template||{};const components=Object.entries(result.component_scores||{});const gates=[...Object.entries(result.mandatory_gates||{}),...Object.entries(result.anti_chase_gates||{})];return <div className="kline-full-evidence"><div className="kline-score-grid expanded"><span><small>校准后总分</small><b>{result.score==null?"—":`${(Number(result.score)*100).toFixed(1)}%`}</b></span><span><small>规则原始分</small><b>{result.base_score==null?"—":`${(Number(result.base_score)*100).toFixed(1)}%`}</b></span><span><small>模板相似度</small><b>{template.similarity==null?"—":`${(Number(template.similarity)*100).toFixed(1)}%`}</b></span><span><small>模板校准</small><b className={Number(template.delta)>=0?"rise":"fall"}>{template.delta==null?"—":`${Number(template.delta)>=0?"+":""}${(Number(template.delta)*100).toFixed(2)}分`}</b></span><span><small>庄线结构分</small><b>{result.features?.zhuang_kline?.score==null?"—":`${(Number(result.features.zhuang_kline.score)*100).toFixed(1)}%`}</b></span><span><small>历史完整度</small><b>{result.available_bars||0}/{result.required_bars||30}根</b></span></div><div className="kline-component-board"><h4>五项规则打分</h4>{components.map(([key,value])=><div key={key}><span>{m30ScoreLabels[key]||key}</span><i><b style={{width:`${Math.max(2,Number(value)*100)}%`}}/></i><strong>{(Number(value)*100).toFixed(1)}</strong></div>)}</div><div className="kline-gate-board"><h4>强制门禁与防追高</h4>{gates.map(([key,value])=><span className={value?"pass":"fail"} key={key}><i>{value?"✓":"×"}</i>{m30GateLabels[key]||key}</span>)}</div></div>}
  const details=Object.entries(result.shape_details||{});const conflict=Number(result.evaluation_features?.conflict_penalty||0);return <div className="kline-full-evidence"><div className="kline-score-grid expanded daily"><span><small>日线综合分</small><b>{result.score==null?"—":`${(Number(result.score)*100).toFixed(1)}%`}</b></span><span><small>命中阈值</small><b>{`${(Number(result.threshold)*100).toFixed(0)}%`}</b></span><span><small>结构冲突扣分</small><b>{`${(conflict*100).toFixed(1)}分`}</b></span><span><small>年线规则历史</small><b>{result.available_bars||0}/{result.required_bars||310}根</b></span></div><div className="daily-template-scoreboard">{details.map(([key,raw])=>{const item:any=raw;return <article className={item.hit?"hit":item.quality_status||""} key={key}><header><div><strong>{dailyTemplateLabels[key]||key}</strong><small>{item.available_bars||0}/{item.required_bars||0}根 · {item.quality_status==="pass"?"可评分":"数据不足"}</small></div><b>{item.score==null?"—":`${(Number(item.score)*100).toFixed(1)}%`}</b></header><div className="daily-gates">{Object.entries(item.gates||{}).map(([gate,value])=><span className={value?"pass":"fail"} key={gate}><i>{value?"✓":"×"}</i>{m30GateLabels[gate]||klineReasonLabels[gate]||gate}</span>)}</div><dl>{Object.entries(item.features||{}).slice(0,10).map(([metric,value])=><div key={metric}><dt>{dailyMetricLabels[metric]||metric}</dt><dd>{klineMetric(value,metric)}</dd></div>)}</dl></article>})}</div></div>;
}

function KlineSimilarity() {
  const [data,setData]=useState<any>(null);const [working,setWorking]=useState(false);const [message,setMessage]=useState("");const [modules,setModules]=useState({m30:true,daily:true});const [limit,setLimit]=useState(80);const [m30Threshold,setM30Threshold]=useState(.72);const [dailyThreshold,setDailyThreshold]=useState(.70);const [refreshIntraday,setRefreshIntraday]=useState(true);const [onlyMatched,setOnlyMatched]=useState(false);const [selectedCode,setSelectedCode]=useState("");
  const load=useCallback(async(scanId?:string)=>{const result=await request(`/kline-similarity?limit=80${scanId?`&scan_id=${encodeURIComponent(scanId)}`:""}`);setData(result);setSelectedCode((current)=>result.results?.some((row:any)=>row.code===current)?current:(result.results?.[0]?.code||""));return result;},[]);
  useEffect(()=>{void load().catch(error=>setMessage(error instanceof Error?error.message:"K线扫描状态读取失败"));},[load]);
  const run=async()=>{if(!modules.m30&&!modules.daily){setMessage("至少启用一种K线形态。 ");return;}setWorking(true);setMessage("正在生成候选池并读取正式K线，盘中同步可能需要数分钟…");try{const created=await request("/kline-similarity/scans",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({modules:Object.entries(modules).filter(([,enabled])=>enabled).map(([key])=>key),limit,m30Threshold,dailyThreshold,refreshIntraday:modules.m30&&refreshIntraday})});for(let attempt=0;attempt<360;attempt+=1){await new Promise(resolve=>setTimeout(resolve,1500));const result=await load(created.scanId);if(result.scan?.status==="completed"){setMessage(result.scan.message||"扫描完成");return;}if(result.scan?.status==="failed")throw new Error(result.scan.error||"扫描失败");}throw new Error("扫描仍在后台运行，请稍后查看");}catch(error){setMessage(error instanceof Error?error.message:"扫描失败");await load().catch(()=>undefined);}finally{setWorking(false);}};
  if(!data)return <Loading label="正在读取K线相似度扫描库"/>;
  const scan=data.scan||{};const allRows=data.results||[];const rows=onlyMatched?allRows.filter((row:any)=>row.matched):allRows;const selected=allRows.find((row:any)=>row.code===selectedCode)||rows[0];const coverage=scan.coverage||{};const migration=data.migration||{};
  return <div className="kline-similarity-workbench">
    <section className="kline-scan-control"><header><div><span>K-LINE SIMILARITY SCAN</span><h3>K线相似度扫描</h3><p>沿用机器选股生产规则：30分钟或日线任一模块命中即可入选，模板只校准相似度，不能改变核心规则命中。</p></div><Badge tone={scan.status==="completed"?"green":scan.status==="failed"?"red":"amber"}>{scan.status==="completed"?"数据就绪":scan.status==="running"?"扫描中":"等待扫描"}</Badge></header>
      <div className="kline-module-switches"><label className={modules.m30?"active":""}><input type="checkbox" checked={modules.m30} onChange={event=>setModules({...modules,m30:event.target.checked})}/><span>30分钟平台突破<small>阈值 {(m30Threshold*100).toFixed(0)}%</small></span></label><label className={modules.daily?"active":""}><input type="checkbox" checked={modules.daily} onChange={event=>setModules({...modules,daily:event.target.checked})}/><span>日线三类形态<small>阈值 {(dailyThreshold*100).toFixed(0)}%</small></span></label></div>
      <div className="kline-thresholds"><label><span>30分钟最低分</span><input type="range" min="50" max="95" value={m30Threshold*100} onChange={event=>setM30Threshold(Number(event.target.value)/100)} disabled={!modules.m30}/></label><label><span>日线最低分</span><input type="range" min="50" max="95" value={dailyThreshold*100} onChange={event=>setDailyThreshold(Number(event.target.value)/100)} disabled={!modules.daily}/></label></div>
      <div className="kline-scan-actions"><label>扫描范围<select value={limit} onChange={event=>setLimit(Number(event.target.value))}><option value={80}>80只 · 快速</option><option value={160}>160只 · 扩展</option><option value={220}>220只 · 完整重扫描</option></select></label><label className="kline-refresh-check"><input type="checkbox" checked={refreshIntraday} onChange={event=>setRefreshIntraday(event.target.checked)} disabled={!modules.m30}/><span>扫描前同步 AKShare 30分钟线</span></label><button onClick={run} disabled={working}>{working?"后台扫描中…":"开始真实扫描"}</button></div>{message&&<p className="kline-scan-message">{message}</p>}
    </section>
    <section className="kline-quality-strip"><article><span>正式日线</span><strong>{coverage.daily_ready??data.market?.daily?.codes??0}</strong><small>{coverage.daily_as_of||data.market?.daily?.asOf||"—"} · BigQuant+Tushare</small></article><article><span>30分钟就绪</span><strong>{coverage.m30_ready??data.market?.m30?.codes??0}</strong><small>{formatDataTime(coverage.m30_as_of||data.market?.m30?.asOf)} · 仅AKShare</small></article><article><span>本批OR命中</span><strong>{scan.hitCount??0}</strong><small>已扫描 {scan.resultCount??0} 只</small></article><article className={migration.verified?"verified":"warning"}><span>U盘迁移校验</span><strong>{migration.files||0}</strong><small>{migration.verified?"逐文件哈希一致":"等待迁移校验"} · {formatNumber((migration.bytes||0)/1024/1024,1)} MB</small></article></section>
    {!scan.status?<div className="kline-first-run"><strong>真实功能已部署，等待首批扫描</strong><span>点击“开始真实扫描”，结果将写入独立数据库并在重启后保留。</span></div>:<section className="kline-result-layout"><div className="kline-candidate-list"><header><div><strong>候选扫描结果</strong><small>{scan.tradeDate||"—"} · OR 命中逻辑</small></div><div className="segmented"><button className={!onlyMatched?"active":""} onClick={()=>setOnlyMatched(false)}>全部</button><button className={onlyMatched?"active":""} onClick={()=>setOnlyMatched(true)}>仅命中</button></div></header><div>{rows.length?rows.slice(0,50).map((row:any)=><button className={`${row.code===selected?.code?"selected ":""}${row.matched?"matched":""}`} key={row.code} onClick={()=>setSelectedCode(row.code)}><b>{String(row.rank).padStart(2,"0")}</b><span><strong>{row.name}</strong><small>{row.code} · {row.industry}</small></span><em>{row.module_hits?.length?row.module_hits.map((module:string)=>module==="m30"?"30m":"日线").join(" + "):"近似观察"}</em><i>{row.best_score==null?"—":`${(Number(row.best_score)*100).toFixed(1)}%`}</i></button>):<div className="kline-no-hit">当前筛选下暂无候选</div>}</div></div>
      <div className="kline-candidate-detail">{selected?<><header><div><span>{selected.matched?"RULE HIT":"NEAR MATCH"}</span><h3>{selected.name}<small>{selected.code} · {selected.industry}</small></h3></div><strong>{selected.best_score==null?"—":`${(Number(selected.best_score)*100).toFixed(1)}%`}</strong></header>{["m30","daily"].filter(module=>selected.modules?.[module]).map(module=>{const result=selected.modules[module];const reasons=result.rejection_reasons||result.risk_reason_codes||[];return <article className="kline-module-detail" key={module}><header><div><Badge tone={result.hit?"green":result.quality_status==="blocked"?"amber":"violet"}>{module==="m30"?"30 MIN":"DAILY"}</Badge><strong>{result.pattern_label}</strong></div><span>{result.score==null?"不可评分":`${(Number(result.score)*100).toFixed(1)}% / ${(Number(result.threshold)*100).toFixed(0)}%`}</span></header><KlineShapeChart bars={result.bars||[]} label={module==="m30"?"30分钟":"日线"}/><KlineScoreEvidence module={module as "m30"|"daily"} result={result}/><div className="kline-evidence-tags">{reasons.length?reasons.slice(0,6).map((reason:string)=><span key={reason}>{klineReasonLabels[reason]||reason}</span>):<span className="pass">核心门禁全部通过</span>}</div></article>})}</>:<div className="kline-first-run"><strong>选择一只股票查看证据</strong></div>}</div></section>}
    <footer className="kline-source-foot"><span>算法：U盘机器选股生产版精确副本</span><span>当前信号数据：正式日线 BigQuant+Tushare · 盘中30分钟 AKShare</span><span>冻结缓存仅供审计，不进入当前打分</span></footer>
  </div>;
}

